import React ,{useState}from 'react'
import { useParams } from 'react-router-dom';
import Button from '../../components/Button';
import ModalContact from '../../components/ModalContact';

import { Property } from '../../types/property';
import Header from '../Home/Header';

import PropertyDetails from './PropertyDetails';


import {DetailsWrapper,BodyContainer,ButtonModalContainer} from './styles';


type Props = {
    property: Property;
}





const PropertyDetail = ()=> {

    const [isModalVisible, setIsModalVisible]= useState(false);
    const params = useParams();
    
    return(
      <DetailsWrapper>
          <Header />
          <BodyContainer>
          
             
               
                  <PropertyDetails   key={`${params.propertyId}`} property={{
            id: 0,
            image: '',
            title: '',
            description: '',
            price: 0,
            beds: 0,
            baths: 0,
            built: 0,
            sqft: 0,
            address: {
              id: 0,
              street: '',
              number: 0,
              city: {
                id: 0,
                name: '',
                county: {
                  id: 0,
                  name: '',
                  state: {
                    id: 0,
                    name: ''
                  }
                }
              }
            }
          }} />
                          
                             
                         
             
          </BodyContainer>
        <ButtonModalContainer>
           
         <Button  onClick={()=>setIsModalVisible(true)}>CONTACT</Button>
         {isModalVisible ? (
         <ModalContact onClose={() => setIsModalVisible(false)}>
            
         </ModalContact>
          ) : null}
       

        </ButtonModalContainer>
      </DetailsWrapper>
    )
}


export default PropertyDetail
